CREATE TEMP TABLE t1(a,b); CREATE TEMP TABLE log(op,x,y); CREATE TEMP TRIGGER t1r1 AFTER INSERT ON t1 BEGIN INSERT INTO log VALUES('I1',new.a,new.b); END; CREATE TEMP TRIGGER t1r2 BEFORE DELETE ON t1 BEGIN INSERT INTO log VALUES('D1',old.a,old.b); END; CREATE TEMP TRIGGER t2r3 AFTER UPDATE ON t1 BEGIN INSERT INTO log VALUES('U1',new.a,new.b); END; INSERT INTO t1 VALUES(1,2),('happy','glad'); UPDATE t1 SET b=9 WHERE a=1; DELETE FROM t1 WHERE a<>'xray' RETURNING a,b,'@'; CREATE TABLE main.capture(k,v1,v2); INSERT INTO main.capture SELECT 't1',a,b FROM temp.t1; INSERT INTO main.capture SELECT op,x,y FROM temp.log;